INSERT INTO knowledge (category, content) VALUES
('后端', 'TCP 三次握手的过程：客户端发送 SYN 报文，服务端回复 SYN+ACK，客户端再回复 ACK。三次握手的核心作用是确认双方的收发能力都正常、初始化序列号，并防止历史连接请求被误建立。'),
('后端', 'TCP 四次挥手的过程：主动方发送 FIN，被动方回复 ACK 后进入 CLOSE_WAIT，被动方发送完数据后发送 FIN，主动方回复 ACK 并进入 TIME_WAIT（持续 2MSL）。TIME_WAIT 保证最后一个 ACK 可达、让旧报文段在网络中彻底消失。'),
('后端', 'TCP 与 UDP 的区别：TCP 面向连接、可靠传输、有序到达，具备流量控制和拥塞控制，适合文件传输、网页浏览等场景；UDP 无连接、尽力而为、低延迟，适合视频通话、直播、DNS 查询等场景。'),
('后端', 'HTTPS 相比 HTTP 多了 TLS 加密层：先通过证书校验服务端身份（防中间人攻击），再用非对称加密协商出对称会话密钥，之后数据用对称加密传输，兼顾安全与性能。'),
('后端', '常见 HTTP 状态码：200 成功、301/302 重定向、304 命中缓存未修改、401 未认证、403 禁止访问、404 资源不存在、500 服务器内部错误、502 网关错误、503 服务不可用、504 网关超时。'),
('后端', 'TCP 粘包与拆包问题：TCP 是字节流协议没有消息边界，发送方多次 write 的数据可能被合并接收（粘包），一次 write 的数据可能被拆分（拆包）。解决方案：定长消息、分隔符、长度前缀，如 Netty 的 LengthFieldBasedFrameDecoder。'),
('后端', '进程与线程的区别：进程是操作系统资源分配的最小单位，拥有独立的内存空间；线程是 CPU 调度的最小单位，共享所属进程的内存。线程创建和切换的开销远小于进程，适合高并发场景。'),
('后端', '死锁产生的四个必要条件：互斥、持有并等待、不可剥夺、循环等待。预防死锁只需破坏其中一个条件，常用手段：资源按序分配、一次性申请全部资源、超时自动释放锁。'),
('后端', '虚拟内存与分页机制：操作系统把磁盘作为内存的扩展，通过页表将虚拟地址映射到物理地址，缺页时发生缺页中断。常用页面置换算法：FIFO、LRU、LFU、Clock 算法。'),
('后端', '用户态与内核态：系统调用通过陷入指令（trap）触发从用户态切换到内核态，目的是保护内核关键资源。频繁的上下文切换会带来性能开销，所以高并发系统要减少不必要的系统调用。'),
('后端', '进程间通信（IPC）方式：管道、消息队列、共享内存、信号量、信号、Socket。共享内存速度最快但需要信号量做同步；Socket 可以跨主机通信，是分布式系统的基础。'),
('后端', 'InnoDB 索引为什么用 B+ 树：B+ 树是矮胖型多路搜索树，单次查询磁盘 IO 次数少；叶子节点通过双向链表串联，天然支持高效范围查询和排序；非叶子节点只存键不存数据，一页能容纳更多键，进一步降低树高。'),
('后端', '聚簇索引与二级索引：InnoDB 主键索引是聚簇索引，叶子节点直接存储整行数据；二级索引叶子节点存储主键值，查询时需要回表再查主键索引。覆盖索引（查询列都在索引中）可以避免回表，是重要的查询优化手段。'),
('后端', '事务的 ACID 特性：原子性靠 undo log 回滚实现，一致性由应用层保证，隔离性通过 MVCC 和锁实现，持久性靠 redo log 保证（先写日志再落盘）。MySQL 默认隔离级别是可重复读。'),
('后端', 'MVCC 多版本并发控制：通过隐藏字段（事务 ID、回滚指针）和 undo log 版本链，配合 ReadView 实现快照读。可重复读隔离级别下 ReadView 在事务第一次查询时生成，因此同一事务多次查询结果一致。'),
('后端', '幻读与当前读：快照读（普通 SELECT）靠 MVCC 避免幻读；当前读（SELECT FOR UPDATE、UPDATE、DELETE）需要加锁，通过间隙锁或临键锁（Record Lock + Gap Lock）防止幻读。'),
('后端', 'MySQL 慢查询排查：使用 EXPLAIN 分析执行计划，关注 type 字段（system/const/ref/range/index/all），避免索引失效：左模糊 LIKE %xx、对索引列做函数运算、隐式类型转换、OR 连接非索引列。'),
('后端', 'MySQL 主从复制原理：主库将变更写入 binlog，从库 IO 线程拉取 binlog 写入中继日志，SQL 线程重放实现数据同步。支持异步复制和半同步复制，用于读写分离、数据备份与容灾。'),
('后端', '分库分表与分布式事务：水平分表按分片键取模或范围拆分，垂直拆分按业务模块拆分。分布式事务方案：两阶段提交、TCC（Try-Confirm-Cancel）、本地消息表、事务消息（RocketMQ）。'),
('后端', 'Redis 缓存三大问题：缓存穿透（查询不存在的数据，用布隆过滤器或缓存空值解决）、缓存击穿（热点 key 过期瞬间大量请求打库，用互斥锁或逻辑过期解决）、缓存雪崩（大量 key 同时过期，过期时间加随机值、多级缓存、限流降级）。'),
('后端', 'Redis 持久化机制：RDB 是定时快照，恢复快但可能丢失最近数据；AOF 是追加写日志，通过 fsync 策略控制刷盘，数据更安全但文件大。Redis 4.0 后支持 RDB+AOF 混合持久化。'),
('后端', 'Redis 过期删除与内存淘汰：过期键采用惰性删除（访问时检查）结合定期删除（周期抽样）；内存达到上限时按策略淘汰：volatile-lru、allkeys-lru、volatile-lfu、allkeys-lfu、volatile-ttl、noeviction。'),
('后端', 'Redis 高可用架构：主从复制提供读扩展，哨兵（Sentinel）监控主节点并在故障时自动切换；Redis Cluster 采用 16384 个哈希槽分片，每个节点负责部分槽，支持水平扩展与自动故障转移。'),
('后端', 'Redis 与 MySQL 数据一致性：常见方案是更新数据库后删除缓存（Cache Aside），高并发下可加延迟双删；或订阅 MySQL binlog 异步刷新缓存。缓存更新失败需要重试补偿机制。'),
('后端', 'Redis 常用数据结构：String（字符串）、Hash（哈希）、List（列表）、Set（集合）、ZSet（有序集合，底层跳表+哈希表）、Bitmap（位图）、HyperLogLog（基数统计）、Geo（地理位置）。'),
('后端', 'JVM 内存区域划分：程序计数器、虚拟机栈、本地方法栈为线程私有；堆（存放对象实例）、方法区（类元数据、常量池，JDK8 后用元空间替代永久代）为线程共享。栈存引用、堆存对象，逃逸分析可做栈上分配。'),
('后端', 'JVM 类加载过程：加载、验证、准备、解析、初始化五个阶段。双亲委派模型：类加载请求逐级向上委派，由父加载器优先加载，防止核心类被篡改；SPI、Tomcat 等场景需要打破双亲委派。'),
('后端', 'JVM 垃圾回收：可达性分析从 GC Roots 出发标记存活对象；分代收集思想下新生代用复制算法（Minor GC），老年代用标记清除或标记整理（Major/Full GC）；常用收集器 G1 将堆划分为 Region，实现可预测的停顿时间。'),
('后端', 'JVM 调优与问题排查工具：jps 查看进程、jstat 查看 GC 状态、jmap 导出堆转储、jstack 抓取线程栈（排查死锁/阻塞）、jinfo 查看配置；OOM 通过堆转储文件 + MAT 分析定位大对象与内存泄漏。'),
('后端', 'HashMap 底层原理：数组 + 链表 + 红黑树（链表长度超过 8 且数组长度大于 64 转红黑树），负载因子 0.75，扩容时重新哈希。HashMap 线程不安全，并发场景用 ConcurrentHashMap（CAS + synchronized 锁桶头）。'),
('后端', '线程池核心参数：核心线程数、最大线程数、阻塞队列、空闲存活时间、拒绝策略（AbortPolicy 抛异常、CallerRunsPolicy 调用者执行、DiscardPolicy 丢弃、DiscardOldestPolicy 丢弃最旧）。核心线程数经验值：CPU 密集型 N+1，IO 密集型 2N。'),
('后端', 'synchronized 与 ReentrantLock 对比：synchronized 是 JVM 内置锁，自动释放，经过偏向锁、轻量级锁、重量级锁升级优化；ReentrantLock 是 JDK 层锁，支持可中断、公平锁、超时获取、多个条件变量；两者都是可重入锁。'),
('后端', 'volatile 关键字：保证变量可见性（写后立即刷新主存）和禁止指令重排序（内存屏障），但不保证原子性，适合修饰状态标志位；原子操作需配合 CAS（compareAndSwap，底层 cmpxchg 指令 + 自旋重试）。'),
('后端', 'Spring Bean 生命周期：实例化、属性填充、Aware 接口回调、BeanPostProcessor 前置处理、InitializingBean/init-method 初始化、BeanPostProcessor 后置处理、使用、DisposableBean/destroy-method 销毁。默认单例作用域。'),
('后端', 'Spring 事务失效的常见场景：方法非 public（默认不代理）、同类内部自调用（this 调用绕过代理）、异常被 try-catch 吞掉、抛出的不是 RuntimeException（默认不回滚，需 rollbackFor）、多线程中调用。'),
('后端', 'Spring 循环依赖解决：依赖三级缓存（一级 singletonObjects 成品、二级 earlySingletonObjects 半成品、三级 singletonFactories 工厂），三级缓存提前暴露未完成 Bean 的引用解决循环依赖；AOP 代理场景下依赖三级缓存保证代理对象一致。');
